BEGIN;
SET TRANSACTION READ ONLY;
SET LOCAL statement_timeout='5s';
SET LOCAL lock_timeout='2s';
SHOW transaction_read_only;
WITH a AS MATERIALIZED (SELECT a.id,a.site_id,a.council_code,a.status,a.decision,a.status_verified_at,a.documents_last_checked_at,a.evidence_refresh_last_checked_at,a.material_evidence_changed_at,a.intelligence_evidence_processed_at FROM public.applications a JOIN public.sites s ON s.id=a.site_id WHERE NOT coalesce(s.excluded,false)), c AS (SELECT council_code,count(*) applications,count(DISTINCT site_id) sites,count(*) FILTER(WHERE status_verified_at IS NOT NULL) verified,count(*) FILTER(WHERE status_verified_at IS NULL) missing FROM a GROUP BY council_code), st AS (SELECT coalesce(status,'[NULL]') status,coalesce(decision,'[NULL]') decision,count(*) n FROM a GROUP BY status,decision), ages AS (SELECT CASE WHEN status_verified_at IS NULL THEN 'missing' WHEN status_verified_at>now() THEN 'future' WHEN status_verified_at>=now()-interval '7 days' THEN '0-7d' WHEN status_verified_at>=now()-interval '30 days' THEN '7-30d' WHEN status_verified_at>=now()-interval '90 days' THEN '30-90d' ELSE '90d+' END age,count(*) n FROM a GROUP BY 1), si AS (SELECT i.id,i.application_id,true has_intelligence FROM public.scheme_intelligence i JOIN a ON a.id=i.application_id)
SELECT jsonb_build_object('utc',now(),'read_only',current_setting('transaction_read_only'),'applications',(SELECT count(*) FROM a),'sites',(SELECT count(DISTINCT site_id) FROM a),'verified',(SELECT count(*) FROM a WHERE status_verified_at IS NOT NULL),'sites_any_verified',(SELECT count(DISTINCT site_id) FROM a WHERE status_verified_at IS NOT NULL),'sites_all_verified',(SELECT count(*) FROM (SELECT site_id FROM a GROUP BY site_id HAVING bool_and(status_verified_at IS NOT NULL)) x),'councils',(SELECT jsonb_agg(c ORDER BY council_code) FROM c),'statuses',(SELECT jsonb_agg(st ORDER BY status,decision) FROM st),'ages',(SELECT jsonb_agg(ages ORDER BY age) FROM ages),'intelligence_records',(SELECT count(*) FROM si),'site_status_narrative_records',(SELECT count(*) FROM public.sites s WHERE NOT coalesce(s.excluded,false) AND s.status_summary IS NOT NULL AND s.status_summary<>''),'allocation_summaries',(SELECT count(*) FROM public.allocation_intelligence_summaries),'allocation_narratives',(SELECT count(*) FROM public.allocation_intelligence_summaries WHERE headline IS NOT NULL AND headline<>''),'allocation_missing_context_hash',(SELECT count(*) FROM public.allocation_intelligence_summaries WHERE headline IS NOT NULL AND headline<>'' AND context_fingerprint IS NULL)) AS inventory;
ROLLBACK;
